export const Escena:React.FC=()=>{const {s}=useS();let tree:React.ReactNode=<Shot i={0}/>;for(let i=1;i<A.length;i++)tree=<Paso t={T(A[i])} tipo={(['forma','alejar','entrar','forma','barrido','forma','alejar'] as const)[i-1]} antes={tree} despues={<Shot i={i}/>} dur={.65}/>;return <AbsoluteFill style={{background:tono(s,[0,en('fabrican'),en('existió')],['#afa68d','#455155','#733e34'])}}>{tree}</AbsoluteFill>};
const VOICE_CUES=[{t:.1,s:'click_01'},{t:en('nunca'),s:'click_02'},{t:en('outlet'),s:'chime_01'},{t:en('sobró'),s:'whoosh_01'},{t:en('descuento'),s:'pop_01'},{t:en('Pero'),s:'whoosh_02'},{t:en('fabrican'),s:'tick_01'},{t:en('tela'),s:'papel_01'},{t:en('costuras'),s:'click_03'},{t:en('precio'),s:'click_04'},{t:en('catorce'),s:'papel_02'},{t:en('cuatro'),s:'tick_02'},{t:en('pidieron'),s:'papel_03'},{t:en('calidad'),s:'pop_03'},{t:en('guía'),s:'whoosh_03'},{t:en('mitad'),s:'ding_01'},{t:en('cien'),s:'tick_01'},{t:en('cuarenta'),s:'tick_02'},{t:en('existió'),s:'pop_02'},{t:en('toca'),s:'papel_01'},{t:en('etiqueta',2),s:'click_01'},{t:en('distinta'),s:'chime_02'},{t:en('Dale'),s:'whoosh_04'}];

// Cada desplazamiento corto del seguimiento tiene un whoosh propio. Las
// palabras de datos conservan prioridad y una separación mínima de 0,27 s.
const CAM_STEPS=Array.from({length:Math.ceil(DUR*2.6/2)},(_,j)=>({t:T(j*2)+.12,s:['whoosh_01','whoosh_02','whoosh_03','whoosh_04','whoosh_05','whoosh_06'][j%6]})).filter((e,j,a)=>e.t<DUR-.2&&VOICE_CUES.every(v=>Math.abs(v.t-e.t)>.28)&&(j===0||e.t-a[j-1].t>.3));
function cameraNudge(s:number){return CAM_STEPS.reduce((v,e,j)=>{const z=s-e.t;return v+(z>=0&&z<.7?Math.sin(z/.7*Math.PI)*(j%2?7:-7):0)},0)}
export const SFX=[...VOICE_CUES,...CAM_STEPS].sort((a,b)=>a.t-b.t).filter((v,i,a)=>i===0||v.t-a[i-1].t>=.27);
